function icon(string $name): string {
 $paths=['home'=>'M3 10 12 3l9 7v10H3z M9 20v-7h6v7','file'=>'M6 3h8l4 4v14H6z M14 3v5h5 M9 12h6 M9 16h6','plus'=>'M12 5v14 M5 12h14','check'=>'m5 12 4 4L19 6','clock'=>'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0','users'=>'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M15 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-3 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0','calendar'=>'M4 5h16v16H4z M8 3v5 M16 3v5 M4 10h16 M8 14h2 M14 14h2','settings'=>'M4 7h16 M4 17h16 M8 4v6 M16 14v6','arrow'=>'M5 12h14 m-5-5 5 5-5 5','download'=>'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4','logout'=>'M9 4H4v16h5 M10 12h11 m-5-5 5 5-5 5','mail'=>'M3 5h18v14H3z m0 0 9 8 9-8','book'=>'M12 6c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V5c-4-1-7-1-10 1z M12 6v15','shield'=>'M12 3 3 7v6c0 4 4 7 9 9 5-2 9-5 9-9V7z m-5 9 3 3 5-6'];
 return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'.($paths[$name]??$paths['file']).'"/></svg>';
}
function navLink(string $target,string $label,string $ic): void { global $page; echo '<a class="nav-item '.($page===$target?'active':'').'" href="/?page='.$target.'">'.icon($ic).'<span>'.e($label).'</span></a>'; }
function badge(string $s): string { return '<span class="badge badge-'.e($s).'">'.e(statusLabel($s)).'</span>'; }
function requestTable(array $list,bool $selectable=false,array $failures=[]): void {
 if (!$list) { echo '<div class="empty">'.icon('file').'<h3>Aquí aparecerán las solicitudes</h3><p>Cuando se registre una solicitud, podrá consultar sus fechas y estado.</p></div>'; return; }
 echo '<div class="table-wrap"><table><thead><tr>'.($selectable?'<th><span class="sr-only">Seleccionar</span></th>':'').'<th>Radicado / funcionario</th><th>Solicitud</th><th>Fecha de registro</th><th>Tiempo</th><th>Estado</th><th><span class="sr-only">Abrir</span></th></tr></thead><tbody>';
 foreach ($list as $r) {
  $selection='';
  if ($selectable) $selection='<td>'.(in_array($r['pending_role']??'',['manager','subsecretary'],true)?'<input type="checkbox" name="approval_ids[]" value="'.(int)$r['pending_approval_id'].'" aria-label="Seleccionar solicitud TH-'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT).'">':'').'</td>';
  echo '<tr id="request-'.(int)$r['id'].'">'.$selection.'<td><a class="strong-link" href="/?page=request&id='.(int)$r['id'].'">TH-'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT).'</a><small>'.e($r['name']??'').'</small></td><td>'.e($r['category']).'<small>'.e(familyLabel($r['family'])).'</small></td><td>'.e(substr($r['created_at'],0,10)).'</td><td>'.e(hours((int)$r['total_minutes'])).'</td><td>'.badge($r['status']).(isset($failures[(int)$r['id']])?'<small class="approval-error" role="alert">No aprobada: '.e($failures[(int)$r['id']]).'</small>':'').'</td><td><a class="icon-button" aria-label="Abrir solicitud '.(int)$r['id'].'" href="/?page=request&id='.(int)$r['id'].'">'.icon('arrow').'</a></td></tr>';
  $electoralCategory=$r['slug']??'';
  if($electoralCategory==='sufragar') {
   $electoralReport=ElectoralCertificate::report($r)??['status'=>'manual'];
   echo '<tr><td colspan="'.($selectable?'7':'6').'"><div class="alert '.(ElectoralCertificate::needsManual($r)?'electoral-alert':'success').'" role="status"><strong>'.e(ElectoralCertificate::summary($electoralReport)).'</strong>';
   if($selectable && ElectoralCertificate::needsManual($r)) echo '<label>Revisión manual de TH-'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT).'<textarea name="electoral_reviews['.(int)$r['id'].']" maxlength="1500" rows="2" placeholder="Registre la cédula, fecha de elecciones y comprobación del plazo de disfrute."></textarea></label>';
   echo '</div></td></tr>';
  }
  if ($selectable && in_array($r['pending_role']??'',['manager','subsecretary'],true)) {
   $periodState=(new Workflow())->periodState((int)$r['id']);
   if ($periodState==='ongoing') echo '<tr><td></td><td colspan="6"><div class="alert warning">El disfrute ya comenzó. Esta aprobación quedará registrada como excepcional.</div><label>Justificación excepcional de TH-'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT).'<textarea name="exception_reasons['.(int)$r['id'].']" maxlength="2500" rows="2" placeholder="Explica el retraso o la urgencia de esta solicitud."></textarea></label></td></tr>';
   if ($periodState==='ended') echo '<tr><td></td><td colspan="6"><span class="approval-error">El periodo de disfrute ya terminó. No puede aprobarse; puede devolverlo o rechazarlo desde el detalle.</span></td></tr>';
  }

 }
 echo '</tbody></table></div>';
}
